INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'guides.doc.convention', 'en', 'In the five headline tiles on each page, a status describes the obligation to ISSUE an e-invoice. Where a business must only be able to RECEIVE one, that is said in the line under the tile. NOT CONFIRMED means we could not source the fact, which is not the same as no requirement.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'guides.doc.convention', 'de', 'In den fünf Kennzahlen-Kacheln jeder Seite beschreibt ein Status die Pflicht, eine E-Rechnung AUSZUSTELLEN. Besteht lediglich eine Pflicht, eine solche EMPFANGEN zu können, steht das in der Zeile unter der Kachel. NICHT BESTÄTIGT heißt, dass wir die Angabe nicht belegen konnten — das ist nicht dasselbe wie keine Pflicht.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'guides.doc.convention', 'fr', 'Dans les cinq tuiles d''en-tête de chaque page, un statut décrit l''obligation d''ÉMETTRE une facture électronique. Lorsqu''une entreprise doit seulement pouvoir en RECEVOIR une, cela figure dans la ligne sous la tuile. NON CONFIRMÉ signifie que nous n''avons pas pu sourcer le fait, ce qui n''est pas la même chose qu''une absence d''obligation.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'guides.doc.convention', 'es', 'En las cinco casillas de cabecera de cada página, un estado describe la obligación de EMITIR una factura electrónica. Cuando la empresa solo debe poder RECIBIRLA, se indica en la línea bajo la casilla. NO CONFIRMADO significa que no pudimos documentar el dato, que no es lo mismo que no haber obligación.');
