INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'guides.gateBody', 'en', 'Subscribing is free. Pick the markets you care about and we will build a one-page briefing for each — the mandate as it stands, the dated timeline, the penalties, the key facts and what to do next — ready to print or save as a PDF.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'guides.gateBody', 'de', 'Das Abonnement ist kostenlos. Wählen Sie die Märkte aus, die für Sie zählen, und wir erstellen für jeden ein einseitiges Briefing — die Pflicht in ihrem aktuellen Stand, die datierte Zeitleiste, die Sanktionen, die wichtigsten Fakten und die nächsten Schritte — fertig zum Drucken oder als PDF.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'guides.gateBody', 'fr', 'L''abonnement est gratuit. Choisissez les marchés qui vous intéressent et nous produirons pour chacun une note d''une page — l''obligation en l''état, le calendrier daté, les sanctions, les faits essentiels et les prochaines étapes — prête à imprimer ou à enregistrer en PDF.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value)
  VALUES ('tracker', 'guides.gateBody', 'es', 'Suscribirse es gratis. Elija los mercados que le interesan y crearemos un informe de una página para cada uno — el mandato tal como está, el calendario con fechas, las sanciones, los datos clave y los próximos pasos — listo para imprimir o guardar en PDF.');
